import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as s}from"./chunks/ON.DXVlsWbj.js";import{_ as a,a as o,b as l}from"./chunks/M-S-SW3e.XAlFcJrn.js";import{_ as t,o as n,c as i,a3 as p}from"./chunks/framework.g9mfNVRQ.js";const x=JSON.parse('{"title":"Pebble","description":"","frontmatter":{"source_hash":"d9a8e52f95","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/smartwatch/pebble.md","filePath":"fr/smartwatch/pebble.md"}'),b={name:"fr/smartwatch/pebble.md"};function d(m,e,c,u,_,h){return n(),i("div",null,[...e[0]||(e[0]=[p('<div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Options montre intelligente<br>   Intégration Pebble</p></div><p>xDrip prend en charge les montres Pebble d&#39;origine (abandonnées en 2016) comme les nouveaux modèles Pebble relancés en 2025 (Pebble 2 Duo, Pebble Time 2).</p><p>Après avoir appairé votre Pebble avec votre téléphone, vous pouvez l&#39;activer dans xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Intégration de la montre Pebble <span class="symbol"><img src="'+s+'" style="zoom:75%;"></span></p></div><p>xDrip installera alors lui-même le cadran (inutile de le télécharger).</p><img src="'+a+'" style="zoom:75%;"><p>Il proposera aussi d&#39;installer l&#39;application du bouton de mise en veille ; si vous l&#39;avez ignorée, vous pourrez l&#39;installer plus tard avec Installer Pebble Apps, en bas de la page.</p><img src="'+o+'" style="zoom:75%;"><p>Vous pouvez choisir différents cadrans.</p><div class="admonition xdripitem"><p class="admonition-title">Choisir le Cadran Pebble</p></div><img src="'+l+'" style="zoom:75%;"><h2 id="new-pebble-models-2025-onwards" tabindex="-1">Nouveaux modèles Pebble (depuis 2025) <a class="header-anchor" href="#new-pebble-models-2025-onwards" aria-label="Permalink to &quot;Nouveaux modèles Pebble (depuis 2025) {#new-pebble-models-2025-onwards}&quot;">​</a></h2><p>Sélectionnez le cadran Pebble Trend Clay Version (All Models) (<a href="https://github.com/jstevensog/xDrip-Pebble-E" target="_blank" rel="noreferrer">xDrip-Pebble-E</a>). Il fonctionne sur tous les modèles Pebble, anciens et nouveaux, en couleurs sur les montres couleur, y compris la nouvelle Pebble Time 2.</p><h2 id="legacy-pebble-models" tabindex="-1">Anciens modèles Pebble <a class="header-anchor" href="#legacy-pebble-models" aria-label="Permalink to &quot;Anciens modèles Pebble {#legacy-pebble-models}&quot;">​</a></h2><p>Avec les versions récentes d&#39;Android, utiliser une ancienne montre Pebble est <a href="https://www.reddit.com/r/pebble/comments/1776bbx/installing_pebble_apk_on_fresh_android_14_setup/" target="_blank" rel="noreferrer">compliqué</a>. Utilisez les ressources de <a href="https://rebble.io/" target="_blank" rel="noreferrer">Rebble</a>.</p><p>Les cadrans Standard, Color Trend et Pebble Classic Trend ont été conçus pour les modèles Pebble d&#39;origine. Le cadran Pebble Trend Clay Version (All Models) fonctionne aussi sur les anciens modèles.</p><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.08.08" target="_blank" rel="noreferrer"><em>Dernière modification le 8/8/2026</em></a></p>',18)])])}const w=t(b,[["render",d]]);export{x as __pageData,w as default};
